package com.example.exception;

import java.util.stream.Collectors;
import lombok.extern.slf4j.Slf4j;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@Slf4j
@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(BizException.class)
    public AjaxResult handleBiz(BizException e) {
        return AjaxResult.error(e.getCode(), e.getMessage());
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public AjaxResult handleValid(MethodArgumentNotValidException e) {
        String detail = e.getBindingResult().getFieldErrors().stream()
            .map(f -> f.getField() + " " + f.getDefaultMessage())
            .collect(Collectors.joining("; "));
        return AjaxResult.error(400, detail);
    }

    @ExceptionHandler(Exception.class)
    public AjaxResult handleUnknown(Exception e) {
        // 对外模糊，对内详细：全栈现场必须落日志
        log.error("未处理异常", e);
        return AjaxResult.error(500, "系统繁忙，请稍后重试");
    }
}

class BizException extends RuntimeException {
    private final int code;

    BizException(int code, String message) {
        super(message);
        this.code = code;
    }

    int getCode() {
        return code;
    }
}

class AjaxResult {
    private final int code;
    private final String msg;

    private AjaxResult(int code, String msg) {
        this.code = code;
        this.msg = msg;
    }

    static AjaxResult error(int code, String msg) {
        return new AjaxResult(code, msg);
    }
}

package com.example.order;

import org.springframework.stereotype.Service;

@Service
public class OrderService {

    private final OrderMapper orderMapper;

    public OrderService(OrderMapper orderMapper) {
        this.orderMapper = orderMapper;
    }

    public String cancel(long orderId, long userId) {
        var order = orderMapper.selectById(orderId);
        if (order == null) {
            throw new BizException(404, "订单不存在");
        }
        if (order.ownerId() != userId) {
            throw new BizException(403, "无权操作他人订单");
        }
        orderMapper.updateStatus(orderId, "CANCELLED");
        return "ok";
    }
}

class BizException extends RuntimeException {
    private final int code;

    BizException(int code, String message) {
        super(message);
        this.code = code;
    }

    int getCode() {
        return code;
    }
}

interface OrderMapper {
    OrderDTO selectById(long id);
    void updateStatus(long id, String status);
}

record OrderDTO(long id, long ownerId, String status) {}
